/** Hero -- generated by the template lab from Figma node 538:40427
 *  (Hero). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- button/shop-now, offer, code, lead;
 *    board copy, editable -- deeper-deals, deeper-deals-2, deeper-deals-3;
 *    photos -- photo, image/photo; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaStroke, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const HERO_538_40427_FIGMA = {
  "button/shop-now": "538:40430", // cta: Shop Now
  "offer": "538:40434", // offer: 20% OFF
  "code": "538:40435", // code: CODE GEARUP20
  "lead": "538:40436", // lead: EXTRA
  "deeper-deals": "538:40440", // text: DEEPER DEALS
  "deeper-deals-2": "538:40441", // text: DEEPER DEALS
  "deeper-deals-3": "538:40442", // text: DEEPER DEALS
  "button/button": "538:40429", // pill: Button
  "art/text-banner-bcakground-texture": "538:40437", // graphic: Text Banner Bcakground Texture
  "image/photo": "538:40428", // photo: BCAndyB_190225_0069 1
} as const;

export function Hero_538_40427({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [HERO_538_40427_FIGMA["button/shop-now"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/button/shop-now`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [HERO_538_40427_FIGMA["offer"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/offer`} contract="lab.offer" layout={layout}
      text={asset.copy.offer || l.text!.chars} />,
    [HERO_538_40427_FIGMA["code"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/code`} contract="lab.code" layout={layout}
      text={asset.copy.code ? l.text!.chars.replace(/^(\s*code\s+)\S+/i, `$1${asset.copy.code}`) : l.text!.chars} />,
    [HERO_538_40427_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [HERO_538_40427_FIGMA["deeper-deals"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/deeper-deals`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_40427_FIGMA["deeper-deals-2"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/deeper-deals-2`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_40427_FIGMA["deeper-deals-3"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/deeper-deals-3`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_40427_FIGMA["button/button"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/button/button/mark`} src="/graphics/named-sale-pill-470x120-16vaikd.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_40427_FIGMA["art/text-banner-bcakground-texture"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/text-banner-bcakground-texture/mark`} src="/graphics/named-sale-text-banner-bcakground-texture-17ttba9.svg"
      fill="#F14222" layout={layout} />,
    [HERO_538_40427_FIGMA["image/photo"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/image/photo`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
